"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 20,
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow application to start and process routes before liveness probe timeout",
  "rationale": "The logs show the app took 1m2s to start and had event loop blocking issues. The liveness probe timeout of 1s is insufficient. Increasing initial delay and timeout aligns with the observed startup time.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
